import React, { useState } from 'react';
import { FaSearch, FaUser, FaShoppingCart, FaSignOutAlt } from 'react-icons/fa';
import './NavMenu.css';

const NavMenu = () => {
  const [showSubMenu, setShowSubMenu] = useState(false);

  const toggleSubMenu = () => {
    setShowSubMenu(!showSubMenu);
  };

  return (
    <nav className="navbar">
      <ul className="nav-list">
        <li className="nav-item">
          <a href="/home" className="nav-link active">Home</a>
        </li>
        <li className="nav-item">
          <a href="/link1" className="nav-link">Link 1</a>
        </li>
        <li className="nav-item">
          <a href="/link2" className="nav-link">Link 2</a>
        </li>
        <li className="nav-item search-item">
          <div className="search-container">
            <FaSearch className="icon" />
            <input type="text" className="search-input" placeholder="Search..." />
          </div>
        </li>
        <li className="nav-item">
          <a href="/profile" className="nav-link" onClick={toggleSubMenu}>
            <FaUser className="icon" />
          </a>
          {showSubMenu && (
            <ul className="submenu">
              <li><a href="/profile">Profile</a></li>
              <li><a href="/settings">Settings</a></li>
            </ul>
          )}
        </li>
        <li className="nav-item">
          <a href="/cart" className="nav-link">
            <FaShoppingCart className="icon" />
          </a>
        </li>
        <li className="nav-item">
          <button className="logout-button">
            <FaSignOutAlt className="icon" />
          </button>
        </li>
      </ul>
    </nav>
  );
}

export default NavMenu;
